html[data-card-desktop]{--android-vh:100dvh;}
/* One phone table layout. Original artwork, cards, status and rule controls. */
html:root[data-card-desktop][data-card-phone] { --card-edge:#bfa06a; --card-ink:#fff2d3; --card-head:34px; --card-table-art:url("data:image/webp;base64,"); }
html:root[data-card-desktop][data-card-phone] body {height:var(--android-vh)!important;overflow:hidden!important;color:var(--card-ink);background:#103a3a!important;background-image:var(--card-table-art)!important;background-position:center!important;background-size:cover!important;}
html:root[data-card-desktop][data-card-phone] .hidden {display:none!important;}
html:root[data-card-desktop][data-card-phone] header {height:var(--card-head)!important;overflow:visible!important;z-index:40;background:linear-gradient(180deg,#050a17c9,transparent)!important;border:0!important;box-shadow:none!important;}
html:root[data-card-desktop][data-card-phone] header > div:first-child {height:100%;padding:2px 8px!important;gap:6px!important;max-width:none!important;flex-wrap:nowrap!important;}
html:root[data-card-desktop][data-card-phone] header > div:first-child > .font-semibold {font-size:11px;letter-spacing:1px;color:#ddc99e;white-space:nowrap;}
html:root[data-card-desktop][data-card-phone] header > div:first-child > .text-xs {font-size:10px;white-space:nowrap;border:0!important;background:none!important;color:#d5c7a5;}
html:root[data-card-desktop][data-card-phone] .phone-card-turn {display:flex;align-items:center;gap:6px;font-size:12px;color:#ffe4a3;margin-left:auto;white-space:nowrap;}
html:root[data-card-desktop][data-card-phone] #stepLbl {font-size:0!important;}
html:root[data-card-desktop][data-card-phone] #stepLbl::after {content:attr(data-phone-label);font-size:12px;}
html:root[data-card-desktop][data-card-phone] .phone-card-round-actions {display:flex;gap:4px;}
html:root[data-card-desktop][data-card-phone] .phone-card-round-actions button {height:30px!important;min-height:30px!important;max-height:30px!important;font-size:11px;padding:2px 8px!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-control {min-height:36px!important;padding:4px 12px;border:1px solid var(--card-edge);border-radius:7px;background:linear-gradient(#173040,#07141e);color:var(--card-ink);font:600 13px/1.2 system-ui;touch-action:manipulation;}
html:root[data-card-desktop][data-card-phone] #phoneCardMenu {height:30px!important;min-height:30px!important;max-height:30px!important;flex:none;border-radius:4px;background:#133b3b;padding:2px 12px;}
html:root[data-card-desktop][data-card-phone] main {height:calc(var(--android-vh) - var(--card-head))!important;max-height:none!important;width:100%!important;max-width:none!important;padding:4px 8px 4px!important;margin:0!important;display:grid!important;grid-template-columns:minmax(0,1fr)!important;grid-template-rows:68px minmax(0,1fr) 68px!important;gap:5px!important;overflow:hidden!important;}
html:root[data-card-desktop][data-card-phone] main > aside {overflow:hidden!important;min-height:0;margin:0!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-roster > .card {padding:0!important;margin:0!important;height:100%;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;}
html:root[data-card-desktop][data-card-phone] main .phone-card-roster > .card > div:first-child {display:none;}
html:root[data-card-desktop][data-card-phone] main #players {display:flex!important;gap:6px!important;height:100%;overflow-x:auto!important;overflow-y:hidden!important;overscroll-behavior:contain;scrollbar-width:thin;}
html:root[data-card-desktop][data-card-phone] main #players > div {flex:1 0 148px;min-width:148px;padding:9px 6px!important;margin:0!important;overflow:visible;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;}
html:root[data-card-desktop][data-card-phone] main #players > div > .flex {position:relative;height:100%;gap:5px!important;align-items:flex-start!important;}
html:root[data-card-desktop][data-card-phone] main #players .grow {min-width:0;}
html:root[data-card-desktop][data-card-phone] main #players .grow > div:first-child {display:flex!important;align-items:center!important;gap:4px!important;flex-wrap:nowrap!important;}
html:root[data-card-desktop][data-card-phone] main #players .font-semibold {font-size:11px;line-height:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#fff0d2;min-width:0;flex:1;}
html:root[data-card-desktop][data-card-phone] main #players .font-semibold > .inline-flex {display:inline-flex!important;margin-left:3px;font-size:9px;}
html:root[data-card-desktop][data-card-phone] main #players .text-xs {font-size:10px;line-height:14px;white-space:nowrap;color:#e7c77f;flex:none;}
html:root[data-card-desktop][data-card-phone] main #players .grow > .flex {gap:2px!important;margin-top:2px!important;font-size:9px!important;white-space:normal;flex-wrap:wrap;}
html:root[data-card-desktop][data-card-phone] main #players .grow > .flex > span {padding:0 2px!important;}
html:root[data-card-desktop][data-card-phone] main #players img.rounded-full {width:46px!important;height:46px!important;min-width:46px;flex:none;border-radius:50%!important;object-fit:cover;border:0!important;box-shadow:none!important;}
html:root[data-card-desktop][data-card-phone] main #players .grow > .flex.items-start {display:none!important;}
html:root[data-card-desktop][data-card-phone] main > .phone-card-battlefield {display:grid!important;grid-template-columns:minmax(140px,.9fr) minmax(190px,1.3fr) 92px!important;grid-template-rows:minmax(0,1fr);gap:12px!important;overflow:visible!important;min-height:0;}
html:root[data-card-desktop][data-card-phone] .phone-card-battlefield:has(#myPlayZone.hidden):not(:has(.phone-card-held > .flex)) {grid-template-columns:minmax(140px,.9fr) minmax(190px,1.3fr) 92px!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-battlefield > * {margin:0!important;min-width:0;min-height:0;}
html:root[data-card-desktop][data-card-phone] .phone-card-battlefield > .phone-card-surface {display:contents!important;}
html:root[data-card-desktop][data-card-phone] .android-card-venues {grid-column:1;grid-row:1;align-self:center;height:90%;padding:4px!important;display:flex;flex-direction:column;min-height:0;background:none!important;border:0!important;border-radius:0!important;box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;}
html:root[data-card-desktop][data-card-phone] .android-card-venues > div:first-child {font-size:10px;letter-spacing:2px;color:#e6cf9b;opacity:1;margin:0 0 6px!important;flex:none;text-align:center;}
html:root[data-card-desktop][data-card-phone] #venues {display:flex!important;gap:8px!important;flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;align-items:center;justify-content:center;}
html:root[data-card-desktop][data-card-phone] #venues > .venue-card {flex:1 0 60px;max-width:110px;min-width:0;height:100%;max-height:150px;overflow:hidden;position:relative;border:0!important;border-radius:3px!important;background:transparent!important;box-shadow:none!important;}
html:root[data-card-desktop][data-card-phone] #venues .venue-card > img {width:100%!important;height:calc(100% - 24px)!important;object-fit:contain;filter:drop-shadow(0 4px 4px #0009);}
html:root[data-card-desktop][data-card-phone] #venues .venue-card > div {padding:2px!important;position:absolute;bottom:0;left:0;right:0;background:none!important;text-align:center;color:#f4dfb0;}
html:root[data-card-desktop][data-card-phone] #venues .venue-card > div > div:first-child {font-size:10px!important;line-height:12px;margin:0!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
html:root[data-card-desktop][data-card-phone] #venues .venue-card > div > div+div {display:none;}
html:root[data-card-desktop][data-card-phone] .android-card-deck {grid-column:3;grid-row:1;align-self:start;height:64px;padding:0!important;display:flex!important;flex-direction:column;align-items:center;justify-content:start!important;gap:2px!important;background:none!important;border:0!important;box-shadow:none!important;backdrop-filter:none!important;min-height:0;}
html:root[data-card-desktop][data-card-phone] .android-card-deck > div:first-child {font-size:10px;white-space:nowrap;color:#e6cf9b;opacity:1;}
html:root[data-card-desktop][data-card-phone] #btnDraw {width:34px!important;height:46px!important;flex-shrink:0;min-height:44px;filter:drop-shadow(3px 5px 2px #0008);}
html:root[data-card-desktop][data-card-phone] #deckImg {width:100%;height:100%;object-fit:contain;}
html:root[data-card-desktop][data-card-phone] #drawHint {display:none!important;}
html:root[data-card-desktop][data-card-phone] #drawHint .emoji {display:none;}
html:root[data-card-desktop][data-card-phone] #myPlayZone:not(.hidden) {display:grid!important;grid-template-columns:minmax(0,1fr)!important;grid-template-rows:0 minmax(0,1fr) 27px;gap:3px;overflow:visible;align-self:stretch;}
html:root[data-card-desktop][data-card-phone] #chooseHint {position:static!important;transform:none!important;margin:0!important;padding:0!important;border:0!important;background:none!important;box-shadow:none!important;font-size:12px!important;line-height:22px;color:#ffe4a5;text-align:center;letter-spacing:1px;}
html:root[data-card-desktop][data-card-phone] #myPlayZone > .grid {display:flex!important;gap:12px!important;min-height:0;align-items:flex-end;justify-content:center;padding:14px 8px 0;overflow:visible;}
html:root[data-card-desktop][data-card-phone] #myPlayZone > .grid > button {height:100%!important;width:auto!important;max-width:46%;aspect-ratio:2/3;min-height:0!important;padding:0!important;border-radius:6px!important;border:1px solid #cbb179!important;background:#1c1930;overflow:hidden!important;box-shadow:0 6px 9px #000b,0 0 8px #8ec5f450;touch-action:manipulation;transform-origin:50% 100%;transition:transform .16s ease,box-shadow .16s ease;}
html:root[data-card-desktop][data-card-phone] #myPlayZone :is([data-card-finish],.card-finish-face) {display:block;width:100%;height:100%;}
html:root[data-card-desktop][data-card-phone] #myPlayZone img {display:block;width:100%!important;height:100%!important;object-fit:contain!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-previews {display:flex;gap:10px;justify-content:center;}
html:root[data-card-desktop][data-card-phone] .phone-card-previews button {min-height:27px!important;height:27px!important;min-width:76px;max-width:45%;font-size:10px;font-weight:500;letter-spacing:1px;border:0;border-radius:3px;background:#111e39bb;color:#dfd2aa;padding:2px 10px;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet {position:fixed;inset:0;z-index:89;display:grid;grid-template-rows:44px minmax(0,1fr);padding:6px max(8px,env(safe-area-inset-right)) 8px max(8px,env(safe-area-inset-left));border:2px solid var(--card-edge);background:linear-gradient(135deg,#071225e8,#020711ed),var(--card-table-art) center/cover;box-shadow:inset 0 0 0 3px #07111b;color:var(--card-ink);}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet-head {display:flex;align-items:center;justify-content:space-between;gap:8px;border-bottom:1px solid #b4915570;padding-bottom:5px;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet-head h2 {font-size:16px;font-weight:700;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet-body {overflow:auto;min-height:0;padding-top:8px;overscroll-behavior:contain;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet-body .phone-card-menu {display:grid;grid-template-columns:1fr 1fr;gap:12px;}
html:root[data-card-desktop][data-card-phone] .phone-card-menu > button {min-height:60px;font-size:16px;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #players {display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #players > div {padding:10px!important;min-width:0;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #players > div > .flex {align-items:flex-start!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #venues {display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;overflow:visible;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #venues > .venue-card {max-width:none;display:grid;grid-template-columns:90px minmax(0,1fr);align-items:center;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #venues .venue-card > img {height:150px!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #venues .venue-card > div {position:static;padding:8px!important;background:none;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #venues .venue-card > div > div {display:block;font-size:13px!important;line-height:1.5!important;white-space:normal;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #logBox {max-height:none!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #discard {max-height:none!important;display:flex;flex-wrap:wrap;}
html:root[data-card-desktop][data-card-phone] .phone-card-sheet #discard img {max-height:100px;height:100px;}
html:root[data-card-desktop][data-card-phone] .phone-card-roster > .card > div:first-child > button {float:right;}
html:root[data-card-desktop][data-card-phone] .phone-card-preview {height:100%;display:flex;justify-content:center;}
html:root[data-card-desktop][data-card-phone] .phone-card-preview img {width:100%;height:100%;object-fit:contain;}
html:root[data-card-desktop][data-card-phone] #modal {padding:0!important;z-index:100!important;align-items:stretch!important;}
html:root[data-card-desktop][data-card-phone] #modal > .card {width:100%!important;max-width:none!important;height:var(--android-vh)!important;max-height:none!important;border:2px solid var(--card-edge)!important;border-radius:0!important;padding:12px 18px!important;overflow:auto!important;background:linear-gradient(135deg,#071225e8,#020711ed),var(--card-table-art) center/cover!important;display:flex;flex-direction:column;justify-content:flex-start;gap:8px;}
html:root[data-card-desktop][data-card-phone] #modal > .card > * {flex-shrink:0;margin:0!important;}
html:root[data-card-desktop][data-card-phone] #modal button {min-height:44px;font-size:14px;white-space:normal;}
html:root[data-card-desktop][data-card-phone] #modal label {min-height:44px;}
html:root[data-card-desktop][data-card-phone] #modal input[type="checkbox"] {width:24px;height:24px;}
html:root[data-card-desktop][data-card-phone] #modal > .card > .flex:last-child {position:sticky;bottom:0;background:#071925;padding:6px!important;}
html:root[data-card-desktop][data-card-phone] #modal img {max-height:calc(var(--android-vh) - 130px)!important;width:auto!important;object-fit:contain;}
html:root[data-card-desktop][data-card-phone] #modal .grid-cols-10 {grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:8px!important;}
html:root[data-card-desktop][data-card-phone] #cardDexOverlay > .card-dex-panel {width:100%!important;height:var(--android-vh)!important;max-height:none!important;border:2px solid var(--card-edge)!important;border-radius:0!important;overflow:hidden!important;padding:0!important;}
html:root[data-card-desktop][data-card-phone] #cardDexOverlay .card-finish-dex-body {display:flex!important;flex-direction:row!important;min-height:0;flex:1;padding:6px!important;gap:8px!important;}
html:root[data-card-desktop][data-card-phone] #cardDexOverlay .card-finish-dex-detail {width:42%!important;min-height:0;overflow:auto;padding:4px!important;border-top:0;}
html:root[data-card-desktop][data-card-phone] #cardDexOverlay .card-finish-dex-list {min-height:0;overflow:auto;}
html:root[data-card-desktop][data-card-phone] #cardDexGrid {grid-template-columns:repeat(4,minmax(0,1fr))!important;}
html:root[data-card-desktop][data-card-phone] #cardDexClose {min-height:36px;min-width:64px;}
html:root[data-card-desktop][data-card-phone] :is(#lawSwapModal,#luffyBoostModal,#rewardModal)>div:not(.absolute) {width:100%!important;max-height:var(--android-vh);overflow:auto;border:2px solid var(--card-edge);border-radius:0;padding:12px!important;}
html:root[data-card-desktop][data-card-phone] :is(#lawSwapModal,#luffyBoostModal) img {max-height:calc(var(--android-vh) - 130px);object-fit:contain;}
html:root[data-card-desktop][data-card-phone] #rewardModal button {min-height:44px;}
html:root[data-card-desktop][data-card-phone] #rewardChestThumb {width:60px;height:60px;}
html:root[data-card-desktop][data-card-phone] #rewardImg {max-height:calc(var(--android-vh) - 45px)!important;object-fit:contain;}
html:root[data-card-desktop][data-card-phone] :is(#idleWarning,#autoTakeoverBanner) {position:fixed!important;left:8px!important;right:8px!important;bottom:4px!important;z-index:80!important;width:auto!important;max-height:100px;overflow:auto;}
@media(max-height:340px){html:root[data-card-desktop][data-card-phone] main {grid-template-rows:68px minmax(0,1fr) 52px!important;}html:root[data-card-desktop][data-card-phone] header > div:first-child > .font-semibold {display:none;}}

html:root[data-card-desktop][data-card-phone] body::before {display:none!important;}
/* Art and primary actions share one continuous tabletop rather than separate tiles. */
html:root[data-card-desktop][data-card-phone] main #players > .current {border:0!important;background:none!important;box-shadow:none!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-held > .flex {height:100%;min-height:0;align-items:center!important;justify-content:center;gap:16px!important;margin:0!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-held > .flex > .shrink-0 {height:100%;min-height:0;max-width:100%;flex-shrink:1!important;}
html:root[data-card-desktop][data-card-phone] #myPlayZone > .grid > button:active:not(:disabled) {transform:translateY(2px);box-shadow:0 1px 4px #0009;}
html:root[data-card-desktop][data-card-phone] #myPlayZone > .grid > button:focus-visible {outline:2px solid #91eee3;outline-offset:-3px;}
html:root[data-card-desktop][data-card-phone] .phone-card-history #logBox:empty::after {content:'等待第一個行動';color:#91ada5;}

/* The original twelve-step tutorial gets a separate reading rail, leaving its
   highlighted controls uncovered. Its original buttons still advance steps. */
html:root[data-card-desktop][data-card-phone][data-card-tutorial] {--card-guide:clamp(220px,36vw,320px);}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] :is(header,main) {width:calc(100% - var(--card-guide))!important;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] header > div:first-child > .font-semibold {display:none;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] .phone-card-battlefield {grid-template-columns:minmax(0,1fr)!important;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial="4"] .phone-card-surface {display:none!important;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] .phone-card-sheet {right:var(--card-guide);}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] .phone-card-sheet #players {grid-template-columns:minmax(0,1fr)!important;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel {left:auto!important;right:0!important;top:0!important;bottom:0!important;transform:none!important;width:var(--card-guide)!important;height:var(--android-vh);border-radius:0;border:2px solid #b49155;display:grid;grid-template-rows:36px minmax(0,1fr);}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel .head {padding:4px 8px;gap:6px;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel .body {padding:8px;display:flex;flex-direction:column;gap:6px;min-height:0;overflow:auto;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel .main {font-size:14px;line-height:1.4;margin:0;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel .sub {font-size:12px;line-height:1.5;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel .tip {font-size:11px;line-height:1.5;margin:0;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel .actions {position:sticky;bottom:0;margin-top:auto;padding-top:6px;gap:4px;background:#080f19;flex:none;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialPanel button {min-height:40px!important;padding:5px!important;font-size:12px;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] :is(#tutorialTopBadge,#tutorialArrow) {display:none!important;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialDim {background:none;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #tutorialFocus {box-shadow:0 0 0 2px #d5ae4870;}

html:root[data-card-desktop][data-card-phone] #playedImg {width:auto!important;max-width:45vw!important;height:calc(var(--android-vh) - 66px)!important;object-fit:contain;}
html:root[data-card-desktop][data-card-phone] #playedOverlay .played-wrap {max-height:100%;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial] #playedOverlay {right:var(--card-guide)!important;}
html:root[data-card-desktop][data-card-phone][data-card-tutorial="4"] main > .phone-card-battlefield > .phone-card-surface {display:none!important;}
html:root[data-card-desktop][data-card-phone] .phone-card-surface > .card {grid-column:auto!important;min-width:0;min-height:0;}

/* The original discard/log nodes are visible throughout the match, not menu-only. */
html:root[data-card-desktop][data-card-phone] .phone-card-history {display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:16px;min-height:0;overflow:hidden;border-top:1px solid #b8aa7a80;background:linear-gradient(180deg,#081124ac,#080b19dd);padding:3px 6px;border-radius:0;}
